import java.util.*;
import java.io.*;

public class Main {
    static final int B = 1000000;
    static final int mod1 = 998244353;
    static final int mod2 = 1000000007;

    static long n, total_counter;
    static List<Integer>[] v = new ArrayList[10];
    static long[] sum = new long[10];
    static int result, total;

    static {
        for (int i = 0; i < 10; i++) {
            v[i] = new ArrayList<>();
        }
    }

    static int compute_mod(long x) {
        long res = (x % mod1 + mod1) % mod1;
        return (int) res;
    }

    static void build_sequence(int depth, long num) {
        total_counter++;
        v[depth].add(compute_mod(total_counter - num));
        if (depth == 6) return;
        for (int digit = 0; digit <= 9; digit++) {
            build_sequence(depth + 1, num * 10 + digit);
        }
    }

    static void evaluate(int depth, long num) {
        if (num > n) return;
        if (depth >= 1) {
            if (num * B > n / 10 && (num + 1) * B - 1 <= n) {
                int factor = 1;
                for (int i = 0; i <= 6; i++, factor *= 10) {
                    int w = compute_mod(total_counter - (long) factor * num);
                    int pos = lowerBound(v[i], compute_mod(mod1 - w));
                    result = (int) ((result + 1L * w * v[i].size() + sum[i] - 1L * mod2 * (v[i].size() - pos)) % mod2);
                }
                total_counter += total;
                return;
            }
            total_counter++;
            result = (int) ((result + compute_mod(total_counter - num)) % mod2);
        }
        int startDigit = (depth == 0) ? 1 : 0;
        for (int digit = startDigit; digit <= 9; digit++) {
            evaluate(depth + 1, num * 10 + digit);
        }
    }

    static int lowerBound(List<Integer> list, int value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine());
        build_sequence(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(v[i]);
            long sumVal = 0;
            for (int val : v[i]) {
                sumVal += val;
            }
            sum[i] = sumVal % mod2;
        }
        total = (int) total_counter;
        total_counter = 0;
        result = 0;
        evaluate(0, 0);
        System.out.println((result + mod2) % mod2);
    }
}
